grid = jnp.array([[(i%16)/15.0, (i//16)/15.0] for i in range(256)], dtype=jnp.float32)
EXC_SRC = jnp.concatenate([jnp.ones(N_S+N_EXC), jnp.zeros(N_INH), jnp.ones(N_M)])
INH_SRC = jnp.concatenate([jnp.zeros(N_S+N_EXC), jnp.ones(N_INH), jnp.zeros(N_M)])

def run_nlp(text, genome):
    sg, ba, ws, aj, gd, lr, to, tm = genome
    sign = EXC_SRC * aj - INH_SRC * jnp.abs(gd)
    toks = jnp.array([ord(c) for c in text], dtype=jnp.int32)

    key = random.PRNGKey(42)
    key, k1 = random.split(key)
    topo = random.bernoulli(k1, 0.15, (N, N)).astype(jnp.float32)
    topo = topo.at[:N_S, N-N_M:].set(1.0)
    W_frozen = topo * ws  # SNN weights FROZEN from blackbox

    @jit
    def step(st, ti):
        v, bd, R, R_bias = st
        co = grid[ti]
        bd2 = (1.0 - ba) * bd + ba * co
        centers = jnp.linspace(0.0, 1.0, N_S//2)  # 16 preferred values
        # Gaussian population code: each neuron tuned to a preferred value
        iext_x = jnp.exp(-0.5 * ((centers - bd2[0]) / 0.08)**2)
        iext_y = jnp.exp(-0.5 * ((centers - bd2[1]) / 0.08)**2)
        iext = jnp.concatenate([iext_x, iext_y, jnp.zeros(N - N_S)]) * sg

        def tick(ts, _):
            tv, tsp, ma = ts
            tv = -70.0 + (tv + 70.0) * jnp.exp(-1.0 / tm)
            tv += iext + jnp.dot(tsp, W_frozen * sign[:, None])
            ns = jnp.where(tv >= (-56.5 + to), 1.0, 0.0)
            return (jnp.where(ns > 0.5, -75.0, tv), ns, ma + ns), None  # ALL spikes

        (v, _, all_sum), _ = lax.scan(tick, (v, jnp.zeros(N), jnp.zeros(N)), jnp.arange(TICKS))

        # Full reservoir readout with quadratic features
        features = all_sum / float(TICKS)  # (128,)
        feat_ext = jnp.concatenate([features, features**2])  # (256,) linear + quadratic
        output = feat_ext @ R + R_bias  # (256,) @ (256,2) + (2,) = (2,)
        output_clipped = jnp.clip(output, 0.0, 1.0)

        # Prediction (nearest grid cell)
        dists = jnp.sum((grid - output_clipped[None, :])**2, axis=1)
        pred = jnp.argmin(dists)
        error = co - output  # (2,)

        # Online delta rule
        R_new = R + 0.02 * jnp.outer(feat_ext, error)
        R_bias_new = R_bias + 0.02 * error

        return (v, bd2, R_new, R_bias_new), pred

    # Initialize readout: 256 features (128 linear + 128 quadratic)
    R = jnp.zeros((N * 2, 2))  # 256 × 2
    R_bias = jnp.array([0.5, 0.5])

    print(f"Target: {text}")
    st = (jnp.full((N,), -70.0), jnp.array([0.5, 0.5]), R, R_bias)

    for ep in range(5001):
        st_run = (jnp.full((N,), -70.0), jnp.array([0.5, 0.5]), st[2], st[3])
        st, preds = lax.scan(step, st_run, toks)
        if ep % 200 == 0:
            correct = sum(1 for p, t in zip(preds, toks) if int(p) == int(t))
            out = "".join([chr(int(p)) if 32 <= p <= 126 else "?" for p in preds])
            print(f"Epoch {ep:04d} | {correct}/{len(text)} | {out}")

